contents.fc88a5d02e806a8d370df5860c360f79d1e0b5f2:
# The mouse is centered for a downward grasp. I will descend while moving the left hand away from the keyboard toward a clear figurine approach.
s=get_observation()['state']
starts={side:list(s[side+'_ee_pose']) for side in ['left','right']}
targets={'left':[-0.45,-0.29,1.09]+q_forward,'right':[0.24,0.0,0.935]+q_down}
for side in ['left','right']:
    if sum(starts[side][j]*targets[side][j] for j in range(3,7))<0:
        targets[side][3:]=[-v for v in targets[side][3:]]
for i in range(16):
    a={}
    for side in ['left','right']:
        p=[starts[side][j]+(i+1)/16*(targets[side][j]-starts[side][j]) for j in range(7)]
        qn=sum(v*v for v in p[3:])**0.5
        p[3:]=[v/qn for v in p[3:]]
        a[side+'_ee_pose']=p
        a[side+'_ee_joint_state']=[1]
    obs,reward,terminated,truncated,info=step(a)
    if terminated or truncated:
        break
print(obs['state'])

contents.2983e2526fc2908b6940a1a934655d8046c96eed:
# The final keyboard approach was unreachable, so a contact correction is unsafe from this pose. I will return both arms toward saved home with open grippers and preserve the stable mouse placement.
s=get_observation()['state']
jstart={side:list(s[side+'_arm_joint_state']) for side in ['left','right']}
for i in range(40):
    a={}
    for side in ['left','right']:
        key=side+'_arm_joint_state'
        a[key]=[jstart[side][j]+(i+1)/40*(home[key][j]-jstart[side][j]) for j in range(len(jstart[side]))]
        a[side+'_ee_joint_state']=[1]
    obs,reward,terminated,truncated,info=step(a)
    if terminated or truncated:
        break
print('done',terminated,truncated,'reward',reward)
print(obs['state'])

